-- CHAMBA 037 — Moderación admin: soft delete + auditoríaSET statement_timeout = '120s';ALTER TABLE jobs  ADD COLUMN IF NOT EXISTS moderated_by UUID REFERENCES profiles(id),  ADD COLUMN IF NOT EXISTS moderation_reason TEXT,  ADD COLUMN IF NOT EXISTS moderated_at TIMESTAMPTZ;COMMENT ON COLUMN jobs.moderation_reason IS 'spam | mistake | admin';CREATE OR REPLACE FUNCTION DROP FUNCTION IF EXISTS admin_moderate_remove_job CASCADE;CREATE OR REPLACE FUNCTION admin_moderate_remove_job(  p_job_id   UUID,  p_admin_id UUID,  p_reason   TEXT DEFAULT 'spam')RETURNS JSONBLANGUAGE plpgsqlSECURITY DEFINERSET search_path = publicAS $$DECLARE  v_job jobs%ROWTYPE;BEGIN  IF p_job_id IS NULL OR p_admin_id IS NULL THEN    RETURN jsonb_build_object('success', false, 'error', 'Parámetros requeridos');  END IF;  IF NOT EXISTS (    SELECT 1 FROM profiles p    WHERE p.id = p_admin_id      AND p.role::text = 'admin'      AND COALESCE(p.is_approved, FALSE) = TRUE  ) THEN    RETURN jsonb_build_object('success', false, 'error', 'Solo administradores');  END IF;  IF p_reason NOT IN ('spam', 'mistake', 'admin') THEN    RETURN jsonb_build_object('success', false, 'error', 'Motivo no válido');  END IF;  SELECT * INTO v_job FROM jobs WHERE id = p_job_id FOR UPDATE;  IF NOT FOUND THEN    RETURN jsonb_build_object('success', false, 'error', 'Servicio no encontrado');  END IF;  IF v_job.status::text <> 'open' THEN    RETURN jsonb_build_object(      'success', false,      'error', 'Solo se pueden retirar solicitudes abiertas (sin técnico asignado)'    );  END IF;  UPDATE job_assignments  SET selection_status = 'rejected'  WHERE job_id = p_job_id    AND selection_status = 'pending';  UPDATE jobs  SET    status            = 'cancelled',    moderated_by      = p_admin_id,    moderation_reason = p_reason,    moderated_at      = NOW(),    updated_at        = NOW()  WHERE id = p_job_id  RETURNING * INTO v_job;  RETURN jsonb_build_object(    'success', true,    'job', row_to_json(v_job)  );END;$$;GRANT EXECUTE ON FUNCTION admin_moderate_remove_job(UUID, UUID, TEXT) TO authenticated, anon;